(E'56fa0398-91c3-5cb6-9167-552cd38561e0'::uuid,E'8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid,E'ffef67d8-1d7b-5083-b833-391dc5e5d160'::uuid,'primary','partially_met','prefilled_iat',E'[B7.2] DR: 10-Yr Plan says trained personnel staff the EOC but need ICS all levels, EOC Management and MDM training.',E'[B7.2] Provisional.',E'[B7.2] Complete EOC Management and ICS courses for all EOC staff.'),
(E'a1387c2c-c66a-50f6-8e29-34c6ec1efca3'::uuid,E'8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid,E'0de6fccd-ee98-53ee-82df-3cbd0fa964a7'::uuid,'primary','partially_met','prefilled_iat',E'[B7.2] DR: 10-Yr Plan says trained personnel staff the EOC but need ICS all levels, EOC Management and MDM training.\n\n[B3.1] F (A6.1/A6.3): group chat, VHF radio, PA and megaphones in use; warnings fail when telecom is down. DR: 10-Yr Plan plans the Leyte DRRMCs Telecom and Response Network.',E'[B7.2] Provisional.\n\n[B3.1] CHECK: score 3 entered, but the evidence still says fewer than 3 independent channels were proven and HF/satellite was not confirmed. Record the three channels observed and the latest radio-check log, or set the score back to 2.',E'[B7.2] Complete EOC Management and ICS courses for all EOC staff.\n\n[B3.1] Inventory comms and test at least 3 independent channels (VHF, HF or satellite, landline/mobile); log a weekly radio check (RDRRMC8 practice: HF Tue/Fri, VHF Wed/Fri).'),
(E'f864a545-4af7-56a7-86e7-035e86a7e68d'::uuid,E'8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid,E'cce0da85-f93c-5692-abfa-d362a173ddce'::uuid,'primary','partially_met','prefilled_iat',E'[B7.2] DR: 10-Yr Plan says trained personnel staff the EOC but need ICS all levels, EOC Management and MDM training.',E'[B7.2] Provisional.',E'[B7.2] Complete EOC Management and ICS courses for all EOC staff.'),
(E'598c17e7-4faa-5940-aeb7-c772b301e208'::uuid,E'8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid,E'ea51b223-25e8-5c6f-937b-a75bfa9b4545'::uuid,'primary','largely_unmet','prefilled_iat',E'[B4.5] F (Admin FGD): job descriptions unclear.\n\n[B7.2] DR: 10-Yr Plan says trained personnel staff the EOC but need ICS all levels, EOC Management and MDM training.',E'[B4.5] Provisional. No job action sheets.\n\n[B7.2] Provisional.',E'[B4.5] Write job action sheets for every EOC role.\n\n[B7.2] Complete EOC Management and ICS courses for all EOC staff.'),
(E'7e994c6c-1bc2-5e58-8247-544f421d66d9'::uuid,E'8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid,E'ecf974a4-85f3-5ad5-b42d-9cf3de314b3e'::uuid,'primary','not_met','prefilled_iat',E'[B7.2] DR: 10-Yr Plan says trained personnel staff the EOC but need ICS all levels, EOC Management and MDM training.\n\n[B2.7] DR: no alternate EOC designated in the documents reviewed; PSCP not completed (A3.4). NDRRMC Memo 131 s.2018 requires an alternate EOC based on the CP/PSCP; CDRA MDA 7 recommends stronger EOC continuity arrangements.',E'[B7.2] Provisional.\n\n[B2.7] No alternate EOC, relocation trigger or relocation procedure. Mandatory gap.',E'[B7.2] Complete EOC Management and ICS courses for all EOC staff.\n\n[B2.7] Designate an alternate EOC outside the primary site''s hazard zones through the PSCP; equip it with a go-kit (radios, laptops, forms, power); write relocation triggers and steps; drill relocation once a year.'),
(E'73c5b777-530b-555d-b9bd-ed7cdc22ebb5'::uuid,E'8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid,E'297f1793-9596-5d86-a0f8-026b9b898895'::uuid,'primary','partially_met','prefilled_iat',E'[B7.3] F: NSED drills (A7.2 = 4); CPs tested for earthquake and flooding (A3.3).',E'[B7.3] Provisional. EOC activation not tested on its own.',E'[B7.3] Add an annual EOC functional exercise.'),
(E'af4b09ec-834a-5748-925c-fa1061c9b7a3'::uuid,E'8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid,E'663bdf10-918b-5ae9-bf2f-3f0bc73e27cd'::uuid,'primary','partially_met','prefilled_iat',E'[B7.3] F: NSED drills (A7.2 = 4); CPs tested for earthquake and flooding (A3.3).\n\n[B7.1] DR: activation SOP (draft, not approved); EOC Manual being prepared under this MOP engagement.',E'[B7.3] Provisional. EOC activation not tested on its own.\n\n[B7.1] Provisional.',E'[B7.3] Add an annual EOC functional exercise.\n\n[B7.1] Complete, approve and distribute the EOC Manual.'),
(E'ec2a49aa-f33c-5dca-8477-47778fe7aec8'::uuid,E'8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid,E'3947e3d5-6010-5d44-b0cb-34831b46f9e7'::uuid,'primary','partially_met','prefilled_iat',E'[B7.3] F: NSED drills (A7.2 = 4); CPs tested for earthquake and flooding (A3.3).',E'[B7.3] Provisional. EOC activation not tested on its own.',E'[B7.3] Add an annual EOC functional exercise.'),
(E'78bfbfd6-b19d-56f7-aeca-c3201843d4a3'::uuid,E'8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid,E'4e137172-605d-5e0a-95ff-1a12d3b71c1c'::uuid,'primary','partially_met','prefilled_iat',E'[B7.3] F: NSED drills (A7.2 = 4); CPs tested for earthquake and flooding (A3.3).',E'[B7.3] Provisional. EOC activation not tested on its own.',E'[B7.3] Add an annual EOC functional exercise.'),
(E'c4cd944e-7ab0-5378-90c8-28a53282ff9b'::uuid,E'8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid,E'cc3671c0-87df-56ee-9ea8-ce01d82a72ac'::uuid,'primary','partially_met','prefilled_iat',E'[B7.3] F: NSED drills (A7.2 = 4); CPs tested for earthquake and flooding (A3.3).',E'[B7.3] Provisional. EOC activation not tested on its own.',E'[B7.3] Add an annual EOC functional exercise.'),
(E'0d49af6b-c1d3-5f86-805d-f96636b17d13'::uuid,E'8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid,E'c46cb353-3069-50eb-9539-814330b88ef3'::uuid,'primary','partially_met','prefilled_iat',E'[B7.3] F: NSED drills (A7.2 = 4); CPs tested for earthquake and flooding (A3.3).\n\n[B2.6] DR: CCTV in the 10-Yr Plan is for hazard monitoring (OpCen integrated EWS); no EOC access-control rule, ID system or visitor log sighted.',E'[B7.3] Provisional. EOC activation not tested on its own.\n\n[B2.6] CHECK: score 3 entered, but the evidence still says no access rule, ID system or visitor log was sighted. Record what was observed (IDs, visitor log, CCTV at entrances) and file it, or set the score back to 2.',E'[B7.3] Add an annual EOC functional exercise.\n\n[B2.6] Write access rules in the EOC Manual: staff IDs, visitor log, badges for agency liaisons, restricted areas (comms, servers); add CCTV at entrances when the OpCen CCTV system is procured.'),
(E'af272d4e-d303-5104-9788-140850a1e39b'::uuid,E'8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid,E'13dfeb7f-52c1-5f84-94a1-4ecfb3e2a0a6'::uuid,'primary','partially_met','prefilled_iat',E'[B7.3] F: NSED drills (A7.2 = 4); CPs tested for earthquake and flooding (A3.3).\n\n[B2.3] OBS (Oct 2026 site visit): the lead assessor sighted generator or UPS capacity, a test log or a 72-hour fuel stock record. The 10-Yr Plan OpCen Program funds fuel and maintenance. DR (issuances 2021-2024, read 6 Nov 2026): CDRRMC Res. 10 s.2021 (15 Dec 2021) asked LEYECO V to run its 2 MW standby generator at Brgy. Alta Vista during widespread outages.',E'[B7.3] Provisional. EOC activation not tested on its own.\n\n[B2.3] To keep this score under Methodology 5.2, file in the Document Vault: the generator rating (kVA), the latest test log and the fuel record. Record which of these were sighted.',E'[B7.3] Add an annual EOC functional exercise.\n\n[B2.3] Inventory the generator (kVA) and UPS; test the generator at full load monthly with a log; keep 72-hour fuel on site and a fuel supply contract for longer events (EOC Checklist, SOP and Supplies sheets).'),
(E'456f4d34-22ea-5eb0-8ad3-1593fe915717'::uuid,E'8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid,E'8f8e0d41-cb66-5946-985e-c24f69736393'::uuid,'primary','not_met','prefilled_iat',E'[B7.3] F: NSED drills (A7.2 = 4); CPs tested for earthquake and flooding (A3.3).\n\n[B2.7] DR: no alternate EOC designated in the documents reviewed; PSCP not completed (A3.4). NDRRMC Memo 131 s.2018 requires an alternate EOC based on the CP/PSCP; CDRA MDA 7 recommends stronger EOC continuity arrangements.',E'[B7.3] Provisional. EOC activation not tested on its own.\n\n[B2.7] No alternate EOC, relocation trigger or relocation procedure. Mandatory gap.',E'[B7.3] Add an annual EOC functional exercise.\n\n[B2.7] Designate an alternate EOC outside the primary site''s hazard zones through the PSCP; equip it with a go-kit (radios, laptops, forms, power); write relocation triggers and steps; drill relocation once a year.'),
(E'a564128e-f904-5318-bb76-d4151da59b7b'::uuid,E'8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid,E'f505f946-1610-5a5d-a764-c6569c4e2fbf'::uuid,'primary','largely_unmet','prefilled_iat',E'[B7.3] F: NSED drills (A7.2 = 4); CPs tested for earthquake and flooding (A3.3).\n\n[B4.1] F (FGDs): Planning, Operations and Admin sections exist; chain of command and team dynamics unclear.',E'[B7.3] Provisional. EOC activation not tested on its own.\n\n[B4.1] Provisional. EOC structure with the five NDRRMC Memo 131 s.2018 functions not defined.',E'[B7.3] Add an annual EOC functional exercise.\n\n[B4.1] Define the EOC organogram (EOC Manager, Operations, Planning, Logistics, Finance/Admin, liaison desks) in EOC Manual Ch.5.'),
(E'849f6cbf-93db-500f-86c2-877195a2ca65'::uuid,E'8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid,E'5d510433-8226-562b-8fcb-3e2328f47e1f'::uuid,'primary','partially_met','prefilled_iat',E'[B7.4] F: AARs conducted (A10.6 = 4).',E'[B7.4] Provisional. EOC improvement plan tracking not sighted.',E'[B7.4] Track AAR actions in an improvement plan.')
  ) as v (id, cycle_id, item_id, site, status, provenance, evidence_observed, gap_remarks, recommended_action)
 where exists (select 1 from public.assessment_cycles c where c.id = v.cycle_id)
on conflict (cycle_id, item_id, site) do update set status = excluded.status, evidence_observed = excluded.evidence_observed,
  gap_remarks = excluded.gap_remarks, recommended_action = excluded.recommended_action
  where eoc_cap_responses.provenance = 'prefilled_iat' and eoc_cap_responses.state = 'draft';

commit;
